import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

const FILE_ICONS = {
  pdf: "fa-file-pdf",
  doc: "fa-file-word",
  docx: "fa-file-word",
  ppt: "fa-file-powerpoint",
  pptx: "fa-file-powerpoint",
  xls: "fa-file-excel",
  xlsx: "fa-file-excel",
};
const DEFAULT_FILE_ICON = "fa-file";

/**
 * CONTENT_API_URL -- a Matrix REST resource acting as an authenticated
 * Content API proxy, confirmed working via the `content-api-picker` debug
 * component, and reused directly by `image-gallery`/`card`. Read from
 * info.env at call time, not editor-configurable.
 */
const ROOT_ID_PARAM_NAME = "rootId";

export default {
  async main(input, info) {
    const { assets = [], parentAsset = "", download = false } = input || {};
    const combinedAssets = await resolveCombinedAssets(assets, parentAsset, info?.env?.CONTENT_API_URL);

    const resolvedList = await Promise.all(
      combinedAssets.map((uri) => resolveAsset(uri, info?.fns)),
    );

    const cardsHtml = resolvedList
      .map((resolved) => renderDocument(resolved, download))
      .filter(Boolean)
      .join("\n");

    return /*html*/`
<div ${componentAttrs('document-list', input)}>
  ${cardsHtml}
</div>
`;
  },
};

/**
 * Combines individually-picked assets with every child of the picked parent
 * (`parentAsset`), de-duplicated by uri in case the same asset is reachable
 * both ways.
 */
async function resolveCombinedAssets(assets, parentAsset, contentApiUrl) {
  const children = await resolveParentChildUris(parentAsset, contentApiUrl);
  const sources = Array.isArray(assets) ? assets : [];
  return [...new Set([...sources, ...children])];
}

/**
 * Resolves `parentAsset`'s children into matrix-asset-uri strings, via a
 * plain unauthenticated fetch() against CONTENT_API_URL -- not info.fns,
 * which has no children-listing capability at all on this tenant. Only each
 * child's `id` is used to rebuild a matrix-asset-uri (reusing parentAsset's
 * own domain); the listing's own metadata is deliberately not relied on, so
 * every child still resolves through the exact same
 * resolveAsset()/renderDocument() path as an individually-picked asset. See
 * document.spec.md assumption 7.
 */
async function resolveParentChildUris(parentAsset, contentApiUrl) {
  const { domain, id: parentId } = parseAssetUri(parentAsset);
  if (!domain || !parentId || !contentApiUrl) return [];

  const url = `${contentApiUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(parentId)}`;

  let body;
  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    body = await res.json();
  } catch {
    return [];
  }

  if (!Array.isArray(body)) return [];
  return body
    .map((item) => item?.id)
    .filter(Boolean)
    .map((id) => `matrix-asset://${domain}/${id}`);
}

function parseAssetUri(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/(\d+)(?::.+)?$/.exec(String(uri ?? ""));
  return { domain: match?.[1] ?? null, id: match?.[2] ?? null };
}

/**
 * Resolves one matrix-asset-uri via fns.resolveUri. The result is an
 * `{ ok, data }` envelope in Storybook mocks but the bare asset on a live
 * page (see card.spec.md assumption 4), so both are accepted; checking the
 * `data` key's presence, not truthiness, keeps a `{ data: null }` "not
 * found" envelope from being read as an asset. Best effort: any failure
 * yields null rather than throwing.
 */
async function resolveAsset(uri, fns) {
  if (!uri) return null;
  try {
    const res = await fns?.resolveUri?.(uri);
    return res && "data" in res ? res.data : (res ?? null);
  } catch {
    return null;
  }
}

function renderDocument(resolved, download) {
  if (!resolved) return "";

  const title = resolved.name || "";
  const href = resolved.url || "";
  const fileType = fileTypeFromUrl(href);
  const fileSize = resolved.attributes?.file_size_readable || "";
  const description = firstMetadataValue(resolved.metadata, "page-description");
  const metaLine = [fileType.toUpperCase(), fileSize].filter(Boolean).join(" | ");

  const descriptionHtml = description
    ? `<p class="document__description">${escHTML(description)}</p>`
    : "";

  return /*html*/`
<div class="document">
  <div class="document__header">
    <div class="document__icon-wrapper">
      <div class="document__icon">
        <i class="fa-thin ${fileIconClass(fileType)}" aria-hidden="true"></i>
      </div>
    </div>
    <div class="document__meta">
      <a href="${escURL(href)}" class="document__title"${download ? " download" : ""}>${escHTML(title)}</a>
      <span class="document__info">${escHTML(metaLine)}</span>
    </div>
  </div>
  ${descriptionHtml}
</div>`;
}

function fileIconClass(fileType) {
  const key = String(fileType ?? "").toLowerCase();
  return FILE_ICONS[key] || DEFAULT_FILE_ICON;
}

/**
 * File type/extension is read from the resolved asset's own URL rather
 * than a metadata field -- reliable regardless of what (if any) type
 * attribute the resolved asset schema exposes. See document.spec.md
 * assumption 1.
 */
function fileTypeFromUrl(url) {
  const match = /\.([a-z0-9]+)(?:[?#].*)?$/i.exec(String(url ?? ""));
  return match ? match[1].toLowerCase() : "";
}

/**
 * Per the real Matrix asset schema (confirmed via `card`'s own live-tested
 * usage), `metadata` is a key-value map where every value is an array of
 * strings -- this reads the first value for a given key.
 */
function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? (value[0] || "") : "";
}
